/**
 * Removes every occurrence of the given tag from the text. Only whole words are taken into
 * account, so removing "#tag" will not affect similar tags like "#tagged" nor partial
 * occurrences inside other words. Tag's text is quoted to avoid being interpreted as a regular
 * expression.
 */
private static String removeTagFromText(String text, Tag tagToRemove) {
    if (text == null || tagToRemove == null || tagToRemove.getText() == null) {
        return text;
    }
    // (?<!\S) and (?!\S) ensure that the tag is surrounded by whitespaces or text boundaries
    return text.replaceAll("(?<!\\S)" + Pattern.quote(tagToRemove.getText()) + "(?!\\S)", "");
}

